import {
    ensureBountyPollCron,
    removeBountyPollCronIfUnused,
} from "../lib/openclawCron.js";

function question(rl: readline.Interface, prompt: string): Promise<string> {
    return new Promise((resolve) => rl.question(prompt, resolve));
}

function parseCandidateId(raw: unknown): number | null {
    if (typeof raw === "number" && Number.isFinite(raw)) return raw;
    if (typeof raw === "string" && /^\d+$/.test(raw.trim())) {
        return parseInt(raw.trim(), 10);
    }
    return null;
}

function candidateField(candidate: any, names: string[]): string | undefined {
    for (const name of names) {
        const value = candidate?.[name];
        if (typeof value === "string" && value.trim()) return value.trim();
    }
    return undefined;
}

function candidatePriceDisplay(candidate: Record<string, unknown>): string {
    const rawPrice =
        candidate.price ??
        candidate.job_offering_price ??
        candidate.jobOfferingPrice ??
        candidate.job_fee ??
        candidate.jobFee ??
        candidate.fee;
    const rawType =
        candidate.priceType ??
        candidate.price_type ??
        candidate.jobFeeType ??
        candidate.job_fee_type;

    if (rawPrice == null) return "Unknown";
    const price = String(rawPrice);
    const type = rawType != null ? String(rawType).toLowerCase() : "";
    if (type === "fixed") return `${price} USDC`;
    if (type === "percentage") return `${price} (${type})`
    return rawType != null ? `${price} ${String(rawType)}` : price;
}

type JsonSchemaProperty = {
    type?: string;
    description?: string;
};

type RequirementSchema = {
    type?: string;
    required?: string[];
    properties?: Record<string, JsonSchemaProperty>;
};

function getCandidateRequirementSchema(candidate: Record<string, unknown>): RequirementSchema | null {
    const schemaCandidate =
        candidate.requirementSchema ??
        candidate.requirement_schema ??
        candidate.requirement;
    if (!schemaCandidate || typeof schemaCandidate !== "object" || Array.isArray(schemaCandidate)) {
        return null;
    }
    return schemaCandidate as RequirementSchema;
}

async function collectRequirementsFromSchema(
    rl: readline.Interface,
    schema: RequirementSchema
): Promise<Record<string, unknown>> {
    const properties = schema.properties ?? {};
    const requiredSet = new Set((schema.required ?? []).filter((k) => typeof k === "string"));
    const keys = Object.keys(properties);
    const out: Record<string, unknown> = {};

    if (keys.length === 0) return out;

    output.log("\n  Fill service requirements:");
    for (const key of keys) {
        const prop = properties[key] ?? {};
        const isRequired = requiredSet.has(key);
        const desc =
            typeof prop.description === "string" && prop.description.trim()
                ? ` - ${prop.description.trim()}`
                : "";
        while (true) {
            const answer = (
                await question(
                    rl,
                    `  ${key}${isRequired ? " [required]" : " [optional]"}${desc}: `
                )
            ).trim();

            if (!answer) {
                if (isRequired) {
                    output.error(`"${key}" is required.`);
                    continue;
                }
                out[key] = "";
                break;
            }
            out[key] = answer;
            break;
        }
    }

    return out;
}

export async function createInteractive(query?: string, sourceChannel?: string): Promise<void> {
    if (output.isJsonMode()) {
        output.fatal(
            "Interactive bounty creation is not supported in --json mode. Use human mode."
        );
    }

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    try {
        const agent = await requireActiveAgent();
        const poster_name = agent.name;

        const querySeed = query?.trim() || "";
        const defaultTitle = querySeed
            ? `${querySeed}`
            : "Need service provider";
        const defaultDescription = querySeed
            ? `${querySeed}`
            : "Need a provider to fulfill this request.";

        const title =
            (await question(rl, `  Title [${defaultTitle}]: `)).trim() ||
            defaultTitle;
        const description =
            (await question(rl, `  Description [${defaultDescription}]: `)).trim() ||
            defaultDescription;
        const budgetRaw = (await question(rl, "  Budget in USD (number, e.g. 50): ")).trim();
        let categoryInput = "digital";
        while (true) {
            const raw = (
                await question(rl, "  Category [digital|physical] (default: digital): ")
            )
                .trim()
                .toLowerCase();
            if (!raw) {
                categoryInput = "digital";
                break;
            }
            if (raw === "digital" || raw === "physical") {
                categoryInput = raw;
                break;
            }
            output.error('Invalid category. Enter only "digital" or "physical".');
        }
        const tags =
            (await question(rl, `  Tags comma-separated [defi,web3,ai]: `)).trim() ||
            "";

        const budget = Number(budgetRaw);
        if (!Number.isFinite(budget) || budget <= 0) {
            output.fatal("Budget must be a positive number.");
        }
        const payload: BountyCreateInput = {
            poster_name,
            poster_wallet_address: agent.walletAddress,
            title,
            description,
            budget,
            category: categoryInput,
            tags,
        };

        const created = await createBounty(payload);

        const active: ActiveBounty = {
            bountyId: created.bountyId,
            createdAt: new Date().toISOString(),
            status: "open",
            title,
            description,
            budget,
            category: categoryInput,
            tags,
            posterName: poster_name,
            posterSecret: created.posterSecret,
            sourceChannel: sourceChannel || "cli",
        };
        saveActiveBounty(active);

        let cronRegistered = false;
        try {
            const cron = ensureBountyPollCron();
            cronRegistered = cron.enabled && cron.created;
            if (cronRegistered) {
                output.log("  OpenClaw cron job registered for `acp bounty poll`.\n");
            }
        } catch {
            // Cron registration failed — include instruction in output
        }

        output.output(
            {
                bountyId: created.bountyId,
                status: "open",
                cronRegistered,
                ...(!cronRegistered ? {
                    cronAction: "required",
                    cronCommand: `openclaw cron add --id "openclaw-acp-bounty-poll" --schedule "*/10 * * * *" --command "cd \\"${ROOT}\\" && npx acp bounty poll --json"`,
                } : {}),
            },
            (data) => {
                output.heading("Bounty Created");
                output.field("Bounty ID", data.bountyId);
                output.field("Status", data.status);
                if (!cronRegistered) {
                    output.log(
                        "\n  IMPORTANT: Register the bounty poll cron job by running:"
                    );
                    output.log(
                        `    openclaw cron add --id "openclaw-acp-bounty-poll" --schedule "*/10 * * * *" --command "cd \\"${ROOT}\\" && npx acp bounty poll --json"`
                    );
                }
                output.log("");
            }
        );
    } finally {
        rl.close();
    }
}

export interface BountyCreateFlags {
    title?: string;
    description?: string;
    budget?: number;
    category?: string;
    tags?: string;
    sourceChannel?: string;
}

export async function createFromFlags(flags: BountyCreateFlags): Promise<void> {
    // Always use the active agent as poster
    const agent = await requireActiveAgent();
    const posterName = agent.name;

    const title = flags.title?.trim();
    const description = flags.description?.trim() || title;
    const budget = flags.budget;
    const category = (flags.category?.trim() || "digital").toLowerCase();
    const tags = flags.tags?.trim() || "";
    const sourceChannel = flags.sourceChannel?.trim() || "cli";

    if (!title) output.fatal("--title is required.");
    if (budget == null || !Number.isFinite(budget) || budget <= 0) {
        output.fatal("--budget must be a positive number.");
    }
    if (category !== "digital" && category !== "physical") {
        output.fatal('--category must be "digital" or "physical".');
    }

    const payload: BountyCreateInput = {
        poster_name: posterName,
        poster_wallet_address: agent.walletAddress,
        title: title!,
        description: description || title!,
        budget: budget!,
        category,
        tags,
    };

    const created = await createBounty(payload);

    const active: ActiveBounty = {
        bountyId: created.bountyId,
        createdAt: new Date().toISOString(),
        status: "open",
        title: title!,
        description: description || title!,
        budget: budget!,
        category,
        tags,
        posterName,
        posterSecret: created.posterSecret,
        ...(sourceChannel ? { sourceChannel } : {}),
    };
    saveActiveBounty(active);

    let cronRegistered = false;
    try {
        const cron = ensureBountyPollCron();
        cronRegistered = cron.enabled && cron.created;
        if (cronRegistered) {
            output.log("  OpenClaw cron job registered for `acp bounty poll`.\n");
        }
    } catch {
        // Cron registration failed — include instruction in output
    }

    output.output(
        {
            bountyId: created.bountyId,
            status: "open",
            sourceChannel: sourceChannel || null,
            cronRegistered,
            ...(!cronRegistered ? {
                cronAction: "required",
                cronCommand: `openclaw cron add --id "openclaw-acp-bounty-poll" --schedule "*/10 * * * *" --command "cd \\"${ROOT}\\" && npx acp bounty poll --json"`,
            } : {}),
        },
        (data) => {
            output.heading("Bounty Created");
            output.field("Bounty ID", data.bountyId);
            output.field("Status", data.status);
            if (data.sourceChannel) output.field("Source Channel", data.sourceChannel);
            if (!cronRegistered) {
                output.log(
                    "\n  IMPORTANT: Register the bounty poll cron job by running:"
                );
                output.log(
                    `    openclaw cron add --id "openclaw-acp-bounty-poll" --schedule "*/10 * * * *" --command "cd \\"${ROOT}\\" && npx acp bounty poll --json"`
                );
            }
            output.log("");
        }
    );
}

export async function create(query?: string, flags?: BountyCreateFlags): Promise<void> {
    // If any structured flag is provided, use the non-interactive path
    if (flags && (flags.title || flags.budget != null)) {
        return createFromFlags(flags);
    }
    return createInteractive(query, flags?.sourceChannel);
}

export async function list(): Promise<void> {
    const bounties = listActiveBounties();
    output.output({ bounties }, (data) => {
        output.heading("Active Bounties");
        if (data.bounties.length === 0) {
            output.log("  No active bounties.\n");
            return;
        }
        for (const b of data.bounties) {
            output.field("Bounty ID", b.bountyId);
            output.field("Status", b.status);
            output.field("Title", b.title);
            if (b.acpJobId) output.field("ACP Job ID", b.acpJobId);
            output.log("");
        }
    });
}

function normalizeCandidateForWatch(candidate: Record<string, unknown>): Record<string, unknown> {
    return {
        id: candidate.id,
        agentName: candidateField(candidate, ["agent_name", "agentName", "name"]) || "(unknown)",
        agentWallet: candidateField(candidate, [
            "agent_wallet", "agentWallet", "agent_wallet_address",
            "agentWalletAddress", "walletAddress", "providerWalletAddress", "provider_address",
        ]) || "",
        offeringName: candidateField(candidate, [
            "job_offering", "jobOffering", "offeringName",
            "jobOfferingName", "offering_name", "name",
        ]) || "",
        price: candidate.price ?? candidate.job_offering_price ?? candidate.jobOfferingPrice ?? candidate.job_fee ?? candidate.jobFee ?? candidate.fee ?? null,
        priceType: candidate.priceType ?? candidate.price_type ?? candidate.jobFeeType ?? candidate.job_fee_type ?? null,
        requirementSchema: candidate.requirementSchema ?? candidate.requirement_schema ?? candidate.requirement ?? null,
    };
}

export async function poll(): Promise<void> {
    const bounties = listActiveBounties();
    const result: {
        checked: number;
        pendingMatch: Array<{
            bountyId: string;
            title: string;
            description: string;
            budget: number;
            sourceChannel?: string;
            candidates: Record<string, unknown>[];
        }>;
        claimedJobs: Array<{
            bountyId: string;
            acpJobId: string;
            title: string;
            jobPhase: string;
            deliverable?: string;
            sourceChannel?: string;
        }>;
        cleaned: Array<{
            bountyId: string;
            status: string;
            sourceChannel?: string;
        }>;
        errors: Array<{
            bountyId: string;
            error: string;
        }>;
    } = {
        checked: 0,
        pendingMatch: [],
        claimedJobs: [],
        cleaned: [],
        errors: [],
    };

    for (const b of bounties) {
        result.checked += 1;
        try {
            // --- Claimed bounties: track ACP job status ---
            if (b.status === "claimed" && b.acpJobId) {
                let jobPhase = "";
                let deliverable: string | undefined;
                try {
                    const jobRes = await client.get(`/acp/jobs/${b.acpJobId}`);
                    const jobData = jobRes.data?.data ?? jobRes.data;
                    jobPhase = String(jobData?.phase ?? "").toUpperCase();
                    deliverable = jobData?.deliverable ?? undefined;
                } catch {
                    // If job fetch fails, skip this bounty for now
                    result.errors.push({
                        bountyId: b.bountyId,
                        error: `Failed to fetch ACP job ${b.acpJobId} status`,
                    });
                    continue;
                }

                const isTerminalJob = jobPhase === "COMPLETED" || jobPhase === "REJECTED" || jobPhase === "EXPIRED";

                if (isTerminalJob) {
                    // Sync bounty status via /job-status endpoint
                    if (b.posterSecret) {
                        try {
                            await syncBountyJobStatus({ bountyId: b.bountyId, posterSecret: b.posterSecret });
                        } catch {
                            // non-fatal — continue with cleanup
                        }
                    }

                    const terminalStatus = jobPhase === "COMPLETED" ? "fulfilled" : jobPhase.toLowerCase();
                    removeActiveBounty(b.bountyId);
                    result.cleaned.push({ bountyId: b.bountyId, status: terminalStatus, ...(b.sourceChannel ? { sourceChannel: b.sourceChannel } : {}) });
                } else {
                    // Job still in progress — save current phase
                    saveActiveBounty({ ...b });
                    result.claimedJobs.push({
                        bountyId: b.bountyId,
                        acpJobId: b.acpJobId,
                        title: b.title,
                        jobPhase,
                        deliverable,
                        ...(b.sourceChannel ? { sourceChannel: b.sourceChannel } : {}),
                    });
                }
                continue;
            }

            // --- Non-claimed bounties: check match status ---
            const remote = await getMatchStatus(b.bountyId);
            const status = String(remote.status).toLowerCase();

            if (status === "fulfilled" || status === "expired" || status === "rejected") {
                removeActiveBounty(b.bountyId);
                result.cleaned.push({ bountyId: b.bountyId, status, ...(b.sourceChannel ? { sourceChannel: b.sourceChannel } : {}) });
                continue;
            }

            const isNewPendingMatch =
                status === "pending_match" &&
                Array.isArray(remote.candidates) &&
                remote.candidates.length > 0 &&
                !b.notifiedPendingMatch;

            saveActiveBounty({
                ...b,
                status: remote.status,
                // Mark as notified once we include it in pendingMatch output
                ...(isNewPendingMatch ? { notifiedPendingMatch: true } : {}),
            });

            if (isNewPendingMatch) {
                const candidates = remote.candidates.map((c) =>
                    normalizeCandidateForWatch(c as Record<string, unknown>)
                );

                result.pendingMatch.push({
                    bountyId: b.bountyId,
                    title: b.title,
                    description: b.description,
                    budget: b.budget,
                    ...(b.sourceChannel ? { sourceChannel: b.sourceChannel } : {}),
                    candidates,
                });
            }
        } catch (e) {
            result.errors.push({
                bountyId: b.bountyId,
                error: e instanceof Error ? e.message : String(e),
            });
        }
    }

    try {
        removeBountyPollCronIfUnused();
    } catch {
        // non-fatal
    }

    output.output(result, (r) => {
        output.heading("Bounty Poll");
        output.field("Checked", r.checked);
        output.field("Pending Match", r.pendingMatch.length);
        output.field("Claimed Jobs", r.claimedJobs.length);
        output.field("Cleaned", r.cleaned.length);
        output.field("Errors", r.errors.length);
        if (r.pendingMatch.length > 0) {
            output.log("\n  Pending Match (candidates ready):");
            for (const p of r.pendingMatch) {
                output.log(
                    `    - Bounty ${p.bountyId}: "${p.title}" — ${p.candidates.length} candidate(s)`
                );
                for (const c of p.candidates) {
                    const price = c.priceType === "fixed"
                        ? `${c.price} USDC`
                        : c.price != null ? String(c.price) : "N/A";
                    output.log(
                        `        ${c.agentName} — ${c.offeringName} (${price})`
                    );
                }
                output.log(
                    `      -> run: acp bounty select ${p.bountyId}`
                );
            }
        }
        if (r.claimedJobs.length > 0) {
            output.log("\n  Claimed Jobs (in progress):");
            for (const j of r.claimedJobs) {
                output.log(
                    `    - Bounty ${j.bountyId}: "${j.title}" — Job ${j.acpJobId} phase: ${j.jobPhase}`
                );
            }
        }
        if (r.cleaned.length > 0) {
            output.log("\n  Cleaned (terminal):");
            for (const c of r.cleaned) {
                output.log(`    - ${c.bountyId}: ${c.status}`);
            }
        }
        if (r.errors.length > 0) {
            output.log("\n  Errors:");
            for (const err of r.errors) {
                output.log(`    - ${err.bountyId}: ${err.error}`);
            }
        }
        output.log("");
    });
}

export async function status(bountyId: string): Promise<void> {
    if (!bountyId) output.fatal("Usage: acp bounty status <bountyId>");
    const active = getActiveBounty(bountyId);
    if (!active) output.fatal(`Bounty not found in local state: ${bountyId}`);

    if (active.posterSecret) {
        try {
            await syncBountyJobStatus({
                bountyId,
                posterSecret: active.posterSecret,
            });
        } catch (e) {
            output.warn(
                `Failed to sync bounty job status: ${e instanceof Error ? e.message : String(e)}`
            );
        }
    }

    const remote = await getMatchStatus(bountyId);
    const normalized = String(remote.status).toLowerCase();
    const isTerminal =
        normalized === "fulfilled" || normalized === "expired" || normalized === "rejected";
    const next = { ...active, status: remote.status };
    if (isTerminal) {
        removeActiveBounty(bountyId);
        try {
            removeBountyPollCronIfUnused();
        } catch {
            // non-fatal
        }
    } else {
        saveActiveBounty(next);
    }

    output.output(
        {
            bountyId,
            local: next,
            remote,
        },
        (data) => {
            output.heading(`Bounty ${data.bountyId}`);
            output.field("Status", data.remote.status);
            output.field("Title", data.local.title);
            output.field("Candidates", data.remote.candidates.length);
            if (isTerminal) {
                output.log("  Local bounty record cleaned up (terminal status).");
            }
            output.log("");
        }
    );

    if (!output.isJsonMode() && String(remote.status).toLowerCase() === "pending_match") {
        const rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
        });
        let shouldSelect = false;
        try {
            const answer = (
                await question(rl, "  Bounty is pending_match. Select provider now? (Y/n): ")
            )
                .trim()
                .toLowerCase();
            shouldSelect = answer === "y" || answer === "yes" || answer === "";
        } finally {
            rl.close();
        }
        if (shouldSelect) {
            await select(bountyId);
        }
    }
}

export async function select(bountyId: string): Promise<void> {
    if (!bountyId) output.fatal("Usage: acp bounty select <bountyId>");
    const active = getActiveBounty(bountyId);
    if (!active) output.fatal(`Bounty not found in local state: ${bountyId}`);
    const posterSecret = active.posterSecret;
    if (!posterSecret) {
        output.fatal("Missing poster secret for this bounty.");
    }

    const match = await getMatchStatus(bountyId);
    if (String(match.status).toLowerCase() !== "pending_match") {
        output.fatal(`Bounty is not pending_match. Current status: ${match.status}`);
    }
    if (!Array.isArray(match.candidates) || match.candidates.length === 0) {
        output.fatal("No candidates available for this bounty.");
    }

    if (output.isJsonMode()) {
        output.output({ bountyId, status: match.status, candidates: match.candidates }, () => { });
        return;
    }

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    try {
        output.heading(`Select Candidate for Bounty ${bountyId}`);
        for (let i = 0; i < match.candidates.length; i++) {
            const c = match.candidates[i] as Record<string, unknown>;
            const candidateId = parseCandidateId(c.id) ?? -1;
            output.log(
                `  [${i + 1}] candidateId=${candidateId} ${JSON.stringify(c)}`
            );
        }
        output.log("  [0] None of these candidates");

        const choiceRaw = (await question(rl, "  Choose candidate number: ")).trim();
        if (choiceRaw === "0") {
            await rejectCandidates({
                bountyId,
                posterSecret,
            });
            saveActiveBounty({
                ...active,
                status: "open",
                selectedCandidateId: undefined,
                acpJobId: undefined,
                notifiedPendingMatch: false,
            });
            output.log(
                "  Rejected current candidates. Bounty moved back to open for new matching.\n"
            );
            return;
        }
        const idx = parseInt(choiceRaw, 10) - 1;
        if (!Number.isInteger(idx) || idx < 0 || idx >= match.candidates.length) {
            output.fatal("Invalid candidate selection.");
        }
        const selected = match.candidates[idx] as Record<string, unknown>;
        const candidateId = parseCandidateId(selected.id);
        if (candidateId == null) output.fatal("Selected candidate has invalid id.");

        const walletDefault = candidateField(selected, [
            "agent_wallet",
            "agentWallet",
            "agent_wallet_address",
            "agentWalletAddress",
            "walletAddress",
            "providerWalletAddress",
            "provider_address",
        ]);
        const offeringDefault = candidateField(selected, [
            "job_offering",
            "jobOffering",
            "offeringName",
            "jobOfferingName",
            "offering_name",
            "name",
        ]);

        const wallet = walletDefault || "";
        const offering = offeringDefault || "";

        if (!wallet) {
            output.fatal(
                "Selected candidate is missing provider wallet (expected agent_wallet or walletAddress fields)."
            );
        }
        if (!offering) {
            output.fatal(
                "Selected candidate is missing job offering (expected job_offering/offeringName fields)."
            );
        }

        const providerName =
            candidateField(selected, ["agent_name", "agentName", "name"]) || "(unknown)";
        const offeringPrice = candidatePriceDisplay(selected);

        output.log("\n  Selected Candidate");
        output.log("  ------------------");
        output.log(`  Provider: ${providerName}`);
        output.log(`  Wallet:   ${wallet}`);
        output.log(`  Offering: ${offering}`);
        output.log(`  Price:    ${offeringPrice}`);
        const confirm = (
            await question(rl, "\n  Continue and create ACP job for this candidate? (Y/n): ")
        )
            .trim()
            .toLowerCase();
        if (!(confirm === "y" || confirm === "yes" || confirm === "")) {
            output.log("  Candidate selection cancelled.\n");
            return;
        }

        const schema = getCandidateRequirementSchema(selected);
        const serviceRequirements =
            schema != null
                ? await collectRequirementsFromSchema(rl, schema)
                : {};

        const job = await client.post<{ data?: { jobId?: number }; jobId?: number }>(
            "/acp/jobs",
            {
                providerWalletAddress: wallet,
                jobOfferingName: offering,
                serviceRequirements,
            }
        );
        const acpJobId = String(job.data?.data?.jobId ?? job.data?.jobId ?? "");
        if (!acpJobId) output.fatal("Failed to create ACP job for selected candidate.");

        await confirmMatch({
            bountyId,
            posterSecret,
            candidateId,
            acpJobId,
        });

        const next: ActiveBounty = {
            ...active,
            status: "claimed",
            selectedCandidateId: candidateId,
            acpJobId,
        };
        saveActiveBounty(next);

        output.output(
            {
                bountyId,
                candidateId,
                acpJobId,
                status: "claimed",
            },
            (data) => {
                output.heading("Bounty Claimed");
                output.field("Bounty ID", data.bountyId);
                output.field("Candidate ID", data.candidateId);
                output.field("ACP Job ID", data.acpJobId);
                output.field("Status", data.status);
                output.log(
                    `\n  Use \`acp job status <jobId>\` to monitor the ACP job.`
                );
                output.log(
                    `  Then run \`acp bounty status ${data.bountyId}\` to sync/update bounty status.\n`
                );
            }
        );
    } finally {
        rl.close();
    }
}

export async function cleanup(bountyId: string): Promise<void> {
    if (!bountyId) output.fatal("Usage: acp bounty cleanup <bountyId>");
    const active = getActiveBounty(bountyId);
    if (!active) {
        output.log(`  Bounty not found locally: ${bountyId}`);
        return;
    }
    removeActiveBounty(bountyId);
    try {
        removeBountyPollCronIfUnused();
    } catch {
        // non-fatal
    }
    output.log(`  Cleaned up bounty ${bountyId}\n`);
}

// =============================================================================
// acp browse <query> — Search and discover agents
// =============================================================================

import client from "../lib/client.js";
import { loadApiKey } from "../lib/config.js";
import * as output from "../lib/output.js";

interface JobOffering {
  name: string;
  description?: string;
  price: number;
  priceType: string;
  requiredFunds?: boolean;
  requirement: Record<string, unknown> | string;
  [key: string]: unknown;
}

interface Resource {
  name: string;
  description?: string;
  url?: string;
  params?: Record<string, unknown>;
  [key: string]: unknown;
}

interface Agent {
  id: string;
  name: string;
  walletAddress: string;
  description: string;
  jobOfferings?: JobOffering[];
  resources?: Resource[];
  [key: string]: unknown;
}

function formatPrice(price: number, priceType?: string): string {
  if (priceType === "fixed") return `${price} USDC`;
  if (priceType === "percentage") return `${(price * 100).toFixed(1)}%`;
  return String(price);
}

export async function browse(query: string): Promise<void> {
  if (!query.trim()) {
    output.fatal("Usage: acp browse <query>");
  }

  try {
    const url = `/acp/agents?query=${encodeURIComponent(query)}`;
    output.log(
      `\n  curl -H "x-api-key: ${loadApiKey()}" "${process.env.ACP_API_URL || "https://claw-api.virtuals.io"}${url}"`
    );
    const agents = await client.get<{ data: Agent[] }>(url);

    if (!agents.data.data || agents.data.data.length === 0) {
      output.fatal(
        `No agents found for "${query}". Run \`acp bounty create "${query}"\` to post a bounty.`
      );
    }

    const data = agents.data.data;

    output.output(data, (agents) => {
      output.heading(`Agents matching "${query}"`);
      for (const agent of agents) {
        output.log(`\n  ${agent.name}`);
        output.field("  Wallet", agent.walletAddress);
        if (agent.description) {
          output.field("  Description", agent.description);
        }

        const offerings = agent.jobOfferings || [];
        if (offerings.length > 0) {
          output.log("    Offerings:");
          for (const o of offerings) {
            const fee = formatPrice(o.price, o.priceType);
            const funds = o.requiredFunds ? " [requires funds]" : "";
            output.log(`      - ${o.name} (${fee}${funds})`);
            if (o.description) {
              output.log(`        ${o.description}`);
            }
            if (o.requirement) {
              const req =
                typeof o.requirement === "string"
                  ? o.requirement
                  : JSON.stringify(o.requirement, null, 2)
                    .split("\n")
                    .join("\n          ");
              output.log(`        Requirement: ${req}`);
            }
          }
        }

        const resources = agent.resources || [];
        if (resources.length > 0) {
          output.log("    Resources:");
          for (const r of resources) {
            output.log(`      - ${r.name}`);
            if (r.description) {
              output.log(`        ${r.description}`);
            }
            if (r.url) {
              output.log(`        URL: ${r.url}`);
            }
            if (r.params) {
              const params = JSON.stringify(r.params, null, 2)
                .split("\n")
                .join("\n          ");
              output.log(`        Params: ${params}`);
            }
          }
        }
      }
      output.log("");
    });
  } catch (e) {
    output.fatal(
      `Browse failed: ${e instanceof Error ? e.message : String(e)}`
    );
  }
}

// =============================================================================
// acp serve deploy railway            — Deploy current agent to Railway
// acp serve deploy railway setup      — Create Railway project for current agent
// acp serve deploy railway status     — Show current agent's deployment status
// acp serve deploy railway logs       — Show current agent's deployment logs
// acp serve deploy railway teardown   — Remove current agent's deployment
// acp serve deploy railway env        — List env vars on current agent's project
// acp serve deploy railway env set    — Set an env var
// acp serve deploy railway env delete — Remove an env var
//
// Each agent gets its own Railway project. Switching agents and deploying
// creates a separate instance — both keep running independently.
// =============================================================================

import * as fs from "fs";
import * as path from "path";
import { execSync } from "child_process";
import readline from "readline";
import * as output from "../lib/output.js";
import {
  readConfig,
  writeConfig,
  getActiveAgent,
  sanitizeAgentName,
  ROOT,
} from "../lib/config.js";
import type { DeployInfo, AgentEntry } from "../lib/config.js";
import { generateDockerfile, generateDockerignore } from "../deploy/docker.js";
import * as railway from "../deploy/railway.js";
import type { LogFilter } from "../deploy/railway.js";

const DOCKERFILE_PATH = path.resolve(ROOT, "Dockerfile");
const DOCKERIGNORE_PATH = path.resolve(ROOT, ".dockerignore");

function getOfferingsRoot(agentName: string): string {
  return path.resolve(
    ROOT,
    "src",
    "seller",
    "offerings",
    sanitizeAgentName(agentName)
  );
}

// -- Helpers --

function prompt(question: string): Promise<string> {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });
  return new Promise((resolve) =>
    rl.question(question, (answer) => {
      rl.close();
      resolve(answer.trim());
    })
  );
}

function installRailwayCli(): void {
  output.log("  Installing Railway CLI...\n");
  execSync("npm install -g @railway/cli", {
    cwd: ROOT,
    stdio: "inherit",
  });
  const check = railway.checkCli();
  if (!check.installed) {
    output.fatal("Installation failed. Try manually: npm install -g @railway/cli");
  }
  output.success(`Railway CLI installed (${check.version})`);
}

async function requireCli(): Promise<void> {
  const { installed } = railway.checkCli();
  if (!installed) {
    const answer = await prompt(
      "  Railway CLI not found. Install it now? (Y/n): "
    );
    if (answer.toLowerCase() === "n") {
      output.fatal(
        "Railway CLI is required. Install manually:\n\n" +
          "  npm install -g @railway/cli\n"
      );
    }
    installRailwayCli();
  }
}

function requireAgent(): AgentEntry {
  const agent = getActiveAgent();
  if (!agent) {
    output.fatal("No active agent. Run `acp setup` first.");
  }
  return agent;
}

/**
 * Ensure the Railway CLI is pointing at the current agent's project.
 * Reads the stored Railway project config for this agent and writes it
 * to .railway/config.json so all subsequent `railway` commands target it.
 */
async function linkToCurrentAgent(): Promise<AgentEntry> {
  await requireCli();
  const agent = requireAgent();
  const config = readConfig();
  const deployInfo = config.DEPLOYS?.[agent.id];

  if (!deployInfo?.railwayConfig) {
    output.fatal(
      `No Railway project for agent "${agent.name}".\n` +
        "  Run `acp serve deploy railway setup` first."
    );
  }

  railway.writeRailwayConfig(deployInfo.railwayConfig);
  return agent;
}

function getDeployInfo(agentId: string): DeployInfo | undefined {
  const config = readConfig();
  return config.DEPLOYS?.[agentId];
}

function saveDeployInfo(agentId: string, info: DeployInfo): void {
  const config = readConfig();
  if (!config.DEPLOYS) config.DEPLOYS = {};
  config.DEPLOYS[agentId] = info;
  writeConfig(config);
}

function removeDeployInfo(agentId: string): void {
  const config = readConfig();
  if (config.DEPLOYS) {
    delete config.DEPLOYS[agentId];
    if (Object.keys(config.DEPLOYS).length === 0) {
      delete config.DEPLOYS;
    }
    writeConfig(config);
  }
}

function listLocalOfferings(agentName: string): string[] {
  const offeringsRoot = getOfferingsRoot(agentName);
  if (!fs.existsSync(offeringsRoot)) return [];
  const entries = fs.readdirSync(offeringsRoot, { withFileTypes: true });
  return entries
    .filter((entry) => {
      if (!entry.isDirectory()) return false;
      const dir = path.join(offeringsRoot, entry.name);
      return (
        fs.existsSync(path.join(dir, "handlers.ts")) &&
        fs.existsSync(path.join(dir, "offering.json"))
      );
    })
    .map((entry) => entry.name);
}

function ensureDockerFiles(): void {
  if (fs.existsSync(DOCKERFILE_PATH)) {
    output.log("  Using existing Dockerfile.");
  } else {
    fs.writeFileSync(DOCKERFILE_PATH, generateDockerfile());
    output.success("Generated Dockerfile");
  }

  if (fs.existsSync(DOCKERIGNORE_PATH)) {
    output.log("  Using existing .dockerignore.");
  } else {
    fs.writeFileSync(DOCKERIGNORE_PATH, generateDockerignore());
    output.success("Generated .dockerignore");
  }
}

// -- Commands --

export async function setup(): Promise<void> {
  // 1. Check CLI (auto-install if missing)
  await requireCli();
  const { version } = railway.checkCli();
  output.log(`  Railway CLI: ${version}`);

  const agent = requireAgent();

  // 2. Check if this agent already has a Railway project
  const existing = getDeployInfo(agent.id);
  if (existing) {
    output.log(`  Agent "${agent.name}" already has a Railway project.`);
    output.log("  Run `acp serve deploy railway` to deploy.\n");
    return;
  }

  // 3. Check login
  if (!railway.isLoggedIn()) {
    output.log("  Logging in to Railway...");
    railway.login();
  }
  output.success("Logged in to Railway");

  // 4. Check if there's already a Railway project linked to this directory
  let railwayConfig = railway.readRailwayConfig();
  if (railwayConfig) {
    output.log(`  Found existing Railway project linked to this directory.`);
  } else {
    // Create new Railway project for this agent
    output.log(`  Creating Railway project for agent "${agent.name}"...`);
    railway.initProject(`acp-${agent.name}`);

    railwayConfig = railway.readRailwayConfig();
    if (!railwayConfig) {
      output.fatal(
        "Failed to read Railway project config after init. Try running `railway init` manually."
      );
    }
  }

  // 6. Save project config for this agent
  // (API key will be set during deploy, after the service is created)
  saveDeployInfo(agent.id, {
    provider: "railway",
    agentName: agent.name,
    offerings: [],
    deployedAt: "",
    railwayConfig,
  });

  output.output(
    { provider: "railway", agent: agent.name, status: "setup_complete" },
    () => {
      output.heading("Railway Setup Complete");
      output.field("Agent", agent.name);
      output.field("Railway Project", `acp-${agent.name}`);
      output.log("\n  Next steps:");
      output.log("    1. Create offerings:   acp sell init <name>");
      output.log("    2. Register on ACP:    acp sell create <name>");
      output.log("    3. Deploy:             acp serve deploy railway\n");
    }
  );
}

export async function deploy(): Promise<void> {
  const agent = await linkToCurrentAgent();

  // Check offerings exist locally
  const offerings = listLocalOfferings(agent.name);
  if (offerings.length === 0) {
    output.fatal(
      "No offerings found. Create at least one offering first:\n\n" +
        "  acp sell init <name>\n" +
        "  acp sell create <name>"
    );
  }

  // Generate Docker files if missing
  ensureDockerFiles();

  // Show what's being deployed
  output.log(`\n  Agent:     ${agent.name}`);
  output.log(`  Offerings: ${offerings.join(", ")}`);
  output.log("");

  // Deploy (this creates the service on first run)
  output.log("  Deploying to Railway...\n");
  railway.up();

  // Link the service if not already linked (railway up creates it but doesn't auto-link)
  if (!railway.hasLinkedService()) {
    const projectName = `acp-${agent.name}`;
    try {
      railway.linkService(projectName);
      output.success(`Linked service ${projectName}`);
    } catch {
      output.warn(
        "Could not auto-link service. Link manually:\n" +
          `  railway service link ${projectName}`
      );
    }
  }

  // Set API key on the service
  const config = readConfig();
  const apiKey = config.LITE_AGENT_API_KEY;
  if (apiKey) {
    try {
      railway.setVariable("LITE_AGENT_API_KEY", apiKey);
      output.success("Set LITE_AGENT_API_KEY on Railway");
    } catch {
      output.warn(
        "Could not set LITE_AGENT_API_KEY. Set it manually:\n" +
          "  acp serve deploy railway env set LITE_AGENT_API_KEY=" + apiKey
      );
    }
  }

  // Update deploy tracking
  const existing = getDeployInfo(agent.id)!;
  saveDeployInfo(agent.id, {
    ...existing,
    offerings,
    deployedAt: new Date().toISOString(),
  });

  output.output(
    { provider: "railway", status: "deployed", agent: agent.name, offerings },
    () => {
      output.heading("Deployed to Railway");
      output.field("Agent", agent.name);
      output.field("Offerings", offerings.join(", "));
      output.log("");
      output.log("  Check status:  acp serve deploy railway status");
      output.log("  View logs:     acp serve deploy railway logs --follow");
      output.log("  Tear down:     acp serve deploy railway teardown\n");
    }
  );
}

export async function status(): Promise<void> {
  const agent = await linkToCurrentAgent();
  const deployInfo = getDeployInfo(agent.id);

  output.heading(`Railway Deployment — ${agent.name}`);
  if (deployInfo && deployInfo.deployedAt) {
    output.field("Offerings", deployInfo.offerings.join(", "));
    output.field("Deployed at", deployInfo.deployedAt);
  }
  output.log("");
  const statusText = railway.getStatus();
  output.log(statusText);
  output.log("");
}

export async function logs(
  follow: boolean = false,
  filter: LogFilter = {}
): Promise<void> {
  await linkToCurrentAgent();
  railway.streamLogs(follow, filter);
}

export async function teardown(): Promise<void> {
  const agent = await linkToCurrentAgent();
  output.log(`  Removing deployment for agent "${agent.name}"...\n`);
  railway.down();

  removeDeployInfo(agent.id);

  output.output(
    { provider: "railway", agent: agent.name, status: "torn_down" },
    () => {
      output.success(`Deployment for "${agent.name}" removed.`);
      output.log("  The Railway project still exists — re-deploy anytime with:");
      output.log("    acp serve deploy railway\n");
    }
  );
}

export async function env(): Promise<void> {
  const agent = await linkToCurrentAgent();
  output.heading(`Railway Env Vars — ${agent.name}`);
  output.log("");
  const vars = railway.listVariables();
  if (vars) {
    output.log(vars);
  } else {
    output.log("  No environment variables set.");
  }
  output.log("");
}

export async function envSet(keyValue: string): Promise<void> {
  await linkToCurrentAgent();

  const eqIdx = keyValue.indexOf("=");
  if (eqIdx === -1) {
    output.fatal(
      "Invalid format. Use: acp serve deploy railway env set KEY=value"
    );
  }

  const key = keyValue.slice(0, eqIdx);
  const value = keyValue.slice(eqIdx + 1);

  if (!key) {
    output.fatal("Key cannot be empty.");
  }

  railway.setVariable(key, value);

  output.output({ action: "set", key }, () => {
    output.success(`Set ${key} on Railway`);
    output.log("  Redeploy for changes to take effect:");
    output.log("    acp serve deploy railway\n");
  });
}

export async function envDelete(key: string): Promise<void> {
  await linkToCurrentAgent();

  if (!key) {
    output.fatal("Usage: acp serve deploy railway env delete <KEY>");
  }

  railway.deleteVariable(key);

  output.output({ action: "deleted", key }, () => {
    output.success(`Deleted ${key} from Railway`);
    output.log("  Redeploy for changes to take effect:");
    output.log("    acp serve deploy railway\n");
  });
}

// =============================================================================
// acp job create <wallet> <offering> [--requirements '{}']
// acp job status <jobId>
// acp job active
// acp job completed
// =============================================================================

import client from "../lib/client.js";
import { formatPrice } from "../lib/config.js";
import * as output from "../lib/output.js";
import { getBountyByJobId } from "../lib/bounty.js";

export async function create(
  agentWalletAddress: string,
  jobOfferingName: string,
  serviceRequirements: Record<string, unknown>
): Promise<void> {
  if (!agentWalletAddress || !jobOfferingName) {
    output.fatal(
      "Usage: acp job create <agentWalletAddress> <jobOfferingName> [--requirements '<json>']"
    );
  }

  try {
    const job = await client.post<{ data: { jobId: number } }>("/acp/jobs", {
      providerWalletAddress: agentWalletAddress,
      jobOfferingName,
      serviceRequirements,
    });

    output.output(job.data, (data) => {
      output.heading("Job Created");
      output.field("Job ID", data.data?.jobId ?? data.jobId);
      output.log(
        "\n  Job submitted. Use `acp job status <jobId>` to check progress.\n"
      );
    });
  } catch (e) {
    output.fatal(
      `Failed to create job: ${e instanceof Error ? e.message : String(e)}`
    );
  }
}

export async function status(jobId: string): Promise<void> {
  if (!jobId) {
    output.fatal("Usage: acp job status <jobId>");
  }

  try {
    const job = await client.get(`/acp/jobs/${jobId}`);

    if (!job?.data?.data) {
      output.fatal(`Job not found: ${jobId}`);
    }

    const data = job.data.data;

    if (job.data.errors) {
      output.output(job.data.errors, (errors) => {
        output.heading(`Job ${jobId}`);
        errors.forEach((error: string, i: number) =>
          output.field(`Error ${i + 1}`, error)
        );
      });
      return;
    }

    const memoHistory = (data.memos || []).map(
      (memo: {
        nextPhase: string;
        content: string;
        createdAt: string;
        status: string;
      }) => ({
        nextPhase: memo.nextPhase,
        content: memo.content,
        createdAt: memo.createdAt,
        status: memo.status,
      })
    );

    const result = {
      jobId: data.id,
      phase: data.phase,
      providerName: data.providerName ?? null,
      providerWalletAddress: data.providerAddress ?? null,
      clientName: data.clientName ?? null,
      clientWalletAddress: data.clientAddress ?? null,
      deliverable: data.deliverable,
      memoHistory,
    };
    const linkedBountyId = getBountyByJobId(String(result.jobId))?.bountyId;

    output.output(result, (r) => {
      output.heading(`Job ${r.jobId}`);
      output.field("Phase", r.phase);
      output.field("Client", r.clientName || "-");
      output.field("Client Wallet", r.clientWalletAddress || "-");
      output.field("Provider", r.providerName || "-");
      output.field("Provider Wallet", r.providerWalletAddress || "-");
      if (r.deliverable) {
        output.log(`\n  Deliverable:\n    ${r.deliverable}`);
      }
      if (r.memoHistory.length > 0) {
        output.log("\n  History:");
        for (const m of r.memoHistory) {
          output.log(`    [${m.nextPhase}] ${m.content} (${m.createdAt})`);
        }
      }
      if (linkedBountyId) {
        output.log(
          `\n  This job is linked to bounty ${linkedBountyId}.`
        );
        output.log(
          `  Run \`acp bounty status ${linkedBountyId}\` to sync bounty status.\n`
        );
      }
      output.log("");
    });
  } catch (e) {
    output.fatal(
      `Failed to get job status: ${e instanceof Error ? e.message : String(e)}`
    );
  }
}

