import {
  readConfig,
  writeConfig,
  type AgentEntry,
} from "./config.js";

const API_URL = process.env.ACP_AUTH_URL || "https://acpx.virtuals.io";

// -- Response types --

export interface AuthUrlResponse {
  authUrl: string;
  requestId: string;
}

export interface AuthStatusResponse {
  token: string;
}

/** Returned by list agents — no API key (never exposed after creation). */
export interface AgentInfoResponse {
  id: string;
  name: string;
  walletAddress: string;
}

/** Returned by create agent — API key shown once. */
export interface AgentKeyResponse {
  id: string;
  name: string;
  apiKey: string;
  walletAddress: string;
}

/** Returned by regenerate — fresh API key for an existing agent. */
export interface RegenerateKeyResponse {
  apiKey: string;
}

// -- HTTP clients --

function apiClient(): AxiosInstance {
  return axios.create({
    baseURL: API_URL,
    headers: { "Content-Type": "application/json" },
  });
}

function apiClientWithSession(sessionToken: string): AxiosInstance {
  return axios.create({
    baseURL: API_URL,
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${sessionToken}`,
    },
  });
}

// -- Session token --

/** Decode the exp claim from a JWT without verifying the signature. */
function getJwtExpiry(token: string): Date | null {
  try {
    const parts = token.split(".");
    if (parts.length !== 3) return null;
    const payload = JSON.parse(Buffer.from(parts[1], "base64url").toString());
    if (typeof payload.exp === "number") {
      return new Date(payload.exp * 1000); // exp is seconds since epoch
    }
    return null;
  } catch {
    return null;
  }
}

export function getValidSessionToken(): string | null {
  const config = readConfig();
  const token = config?.SESSION_TOKEN?.token;
  if (!token) return null;

  const expiry = getJwtExpiry(token);
  if (!expiry || expiry <= new Date()) return null;
  return token;
}

export function storeSessionToken(token: string): void {
  const config = readConfig();
  writeConfig({ ...config, SESSION_TOKEN: { token } });
}

// -- Auth API --

export async function getAuthUrl(): Promise<AuthUrlResponse> {
  const { data } = await apiClient().get<{ data: AuthUrlResponse }>(
    "/api/auth/lite/auth-url"
  );
  return data.data;
}

export async function getAuthStatus(requestId: string): Promise<AuthStatusResponse> {
  const { data } = await apiClient().get<{ data: AuthStatusResponse }>(
    `/api/auth/lite/auth-status?requestId=${requestId}`
  );
  return data.data;
}

// -- Agent API --

/** Fetch all agents belonging to the authenticated user. No API keys returned. */
export async function fetchAgents(sessionToken: string): Promise<AgentInfoResponse[]> {
  const { data } = await apiClientWithSession(sessionToken).get<{
    data: AgentInfoResponse[];
  }>("/api/agents/lite");
  return data.data;
}

/** Create a new agent for the authenticated user. API key returned once. */
export async function createAgentApi(
  sessionToken: string,
  agentName: string
): Promise<AgentKeyResponse> {
  const { data } = await apiClientWithSession(sessionToken).post<{
    data: AgentKeyResponse;
  }>("/api/agents/lite/key", {
    data: { name: agentName.trim() },
  });
  return data.data;
}

/** Regenerate the API key for an existing agent. Returns a fresh key. */
export async function regenerateApiKey(
  sessionToken: string,
  walletAddress: string
): Promise<RegenerateKeyResponse> {
  const { data } = await apiClientWithSession(sessionToken).post<{
    data: RegenerateKeyResponse;
  }>(`/api/agents/lite/${walletAddress}/regenerate-api`);
  return data.data;
}

// -- Login (polling-based, no stdin required) --

/** How often to poll the auth status endpoint (ms). */
const AUTH_POLL_INTERVAL_MS = 5_000;

/** How long to wait for the user to authenticate before timing out (ms). */
const AUTH_TIMEOUT_MS = 5 * 60 * 1_000;

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Login flow. Opens browser / prints link, then polls until authenticated
 * or timed out. No stdin interaction required — works in any runtime.
 */
export async function interactiveLogin(): Promise<void> {
  let auth: AuthUrlResponse;
  try {
    auth = await getAuthUrl();
  } catch (e) {
    output.fatal(
      `Could not get login link: ${e instanceof Error ? e.message : String(e)}`
    );
  }

  const { authUrl, requestId } = auth;
  output.log(`  Opening browser...`);
  openUrl(authUrl);
  output.log(`  Login link: ${authUrl}\n`);
  output.log(`  Waiting for authentication (timeout: ${AUTH_TIMEOUT_MS / 1_000}s)...\n`);

  const deadline = Date.now() + AUTH_TIMEOUT_MS;
  let elapsed = 0;

  while (Date.now() < deadline) {
    await sleep(AUTH_POLL_INTERVAL_MS);
    elapsed += AUTH_POLL_INTERVAL_MS;

    try {
      const status = await getAuthStatus(requestId);
      if (status.token) {
        storeSessionToken(status.token);
        output.success("Login success. Session stored.\n");
        return;
      }
    } catch {
      // Auth not ready yet or transient error — keep polling
    }

    // Progress indicator every 15s (3 polls)
    if (elapsed % 15_000 === 0) {
      const remaining = Math.round((deadline - Date.now()) / 1_000);
      output.log(`  Still waiting... (${remaining}s remaining)`);
    }
  }

  output.fatal(
    `Authentication timed out after ${AUTH_TIMEOUT_MS / 1_000}s. Run \`acp login\` to try again.`
  );
}

/**
 * Ensure we have a valid session token. If expired/missing, auto-prompts login.
 * Returns the valid session token, or calls process.exit if login fails.
 */
export async function ensureSession(): Promise<string> {
  const existing = getValidSessionToken();
  if (existing) return existing;

  output.warn("Session expired or not found. Logging in...\n");
  await interactiveLogin();

  const token = getValidSessionToken();
  if (!token) {
    output.fatal("Login failed. Cannot continue.");
  }
  return token;
}

// -- Agent sync --

/**
 * Merge server agents into local config. Returns the merged list.
 * Server does NOT return API keys — only id, name, walletAddress.
 * Local API keys (from create/regenerate) are preserved.
 */
export function syncAgentsToConfig(serverAgents: AgentInfoResponse[]): AgentEntry[] {
  const config = readConfig();
  const localAgents = config.agents ?? [];

  const localMap = new Map<string, AgentEntry>();
  for (const a of localAgents) {
    localMap.set(a.id, a);
  }

  const merged: AgentEntry[] = serverAgents.map((s) => {
    const local = localMap.get(s.id);
    return {
      id: s.id,
      name: s.name,
      walletAddress: s.walletAddress,
      apiKey: local?.apiKey, // preserve local key if we have one
      active: local?.active ?? false,
    };
  });

  writeConfig({ ...config, agents: merged });
  return merged;
}

// =============================================================================
// Bounty API + local active-bounty state management.
// =============================================================================

import axios from "axios";
import * as fs from "fs";
import * as path from "path";
import { ROOT } from "./config.js";

export type BountyStatus =
    | "open"
    | "pending_match"
    | "claimed"
    | "fulfilled"
    | "expired"
    | "rejected";

export interface BountyCreateInput {
    poster_name: string;
    poster_wallet_address: string;
    poster_email?: string;
    title: string;
    description: string;
    budget: number;
    category: string;
    tags: string;
}

export interface BountyMatchCandidate {
    id: number;
    name?: string;
    walletAddress?: string;
    offeringName?: string;
    [key: string]: unknown;
}

export interface BountyMatchStatusResponse {
    status: BountyStatus | string;
    candidates: BountyMatchCandidate[];
    [key: string]: unknown;
}

export interface ActiveBounty {
    bountyId: string;
    createdAt: string;
    status: BountyStatus | string;
    title: string;
    description: string;
    budget: number;
    category: string;
    tags: string;
    posterName: string;
    posterSecret: string;
    selectedCandidateId?: number;
    acpJobId?: string;
    /** Set to true after the agent has been notified about pending_match candidates. */
    notifiedPendingMatch?: boolean;
    /** Channel where this bounty was created (e.g. "telegram", "webchat") for routing notifications. */
    sourceChannel?: string;
}

interface ActiveBountiesFile {
    bounties: ActiveBounty[];
}

const api = axios.create({
    baseURL: process.env.ACP_BOUNTY_API_URL || "https://bounty.virtuals.io/api/v1",
    headers: { "Content-Type": "application/json" },
});

export const BOUNTY_STATE_PATH = path.resolve(ROOT, "active-bounties.json");

function extractData<T>(raw: any): T {
    if (raw && typeof raw === "object" && "data" in raw) {
        return raw.data as T;
    }
    return raw as T;
}

function ensureParent(filePath: string): void {
    const parent = path.dirname(filePath);
    fs.mkdirSync(parent, { recursive: true });
}

function readState(): ActiveBountiesFile {
    if (!fs.existsSync(BOUNTY_STATE_PATH)) return { bounties: [] };
    try {
        const raw = JSON.parse(fs.readFileSync(BOUNTY_STATE_PATH, "utf-8"));
        if (Array.isArray(raw?.bounties)) {
            return { bounties: raw.bounties as ActiveBounty[] };
        }
    } catch {
        return { bounties: [] };
    }
    return { bounties: [] };
}

function writeState(next: ActiveBountiesFile): void {
    ensureParent(BOUNTY_STATE_PATH);
    fs.writeFileSync(BOUNTY_STATE_PATH, JSON.stringify(next, null, 2) + "\n");
}

export function listActiveBounties(): ActiveBounty[] {
    return readState().bounties;
}

export function getActiveBounty(bountyId: string): ActiveBounty | undefined {
    return readState().bounties.find((b) => b.bountyId === bountyId);
}

export function getBountyByJobId(jobId: string): ActiveBounty | undefined {
    return readState().bounties.find((b) => b.acpJobId === jobId);
}

export function saveActiveBounty(bounty: ActiveBounty): void {
    const state = readState();
    const idx = state.bounties.findIndex((b) => b.bountyId === bounty.bountyId);
    if (idx >= 0) {
        state.bounties[idx] = bounty;
    } else {
        state.bounties.push(bounty);
    }
    writeState(state);
}

export function removeActiveBounty(bountyId: string): void {
    const state = readState();
    state.bounties = state.bounties.filter((b) => b.bountyId !== bountyId);
    writeState(state);
}

export async function createBounty(
    input: BountyCreateInput
): Promise<{ bountyId: string; posterSecret: string; raw: unknown }> {
    const res = await api.post("/bounties/", input);
    const body = extractData<any>(res.data);

    const bountyNode = body?.bounty && typeof body.bounty === "object" ? body.bounty : body;

    const bountyId =
        bountyNode?.id ??
        bountyNode?.bounty_id ??
        bountyNode?.bountyId ??
        body?.id ??
        body?.bounty_id ??
        body?.bountyId;
    const posterSecret =
        body?.poster_secret ??
        body?.posterSecret ??
        body?.data?.poster_secret ??
        body?.data?.posterSecret;

    if (!bountyId || !posterSecret) {
        throw new Error("Invalid create bounty response: missing id or poster_secret");
    }

    return {
        bountyId: String(bountyId),
        posterSecret: String(posterSecret),
        raw: body,
    };
}

export async function getMatchStatus(
    bountyId: string
): Promise<BountyMatchStatusResponse> {
    const res = await api.get(`/bounties/${encodeURIComponent(bountyId)}/match-status`);
    const body = extractData<any>(res.data);

    return {
        ...body,
        status: String(body?.status ?? ""),
        candidates: Array.isArray(body?.candidates) ? body.candidates : [],
    };
}

export async function confirmMatch(params: {
    bountyId: string;
    posterSecret: string;
    candidateId: number;
    acpJobId: string;
}): Promise<unknown> {
    const { bountyId, posterSecret, candidateId, acpJobId } = params;
    const res = await api.post(
        `/bounties/${encodeURIComponent(bountyId)}/confirm-match`,
        {
            poster_secret: posterSecret,
            candidate_id: candidateId,
            acp_job_id: acpJobId,
        }
    );
    return extractData<unknown>(res.data);
}

export async function rejectCandidates(params: {
    bountyId: string;
    posterSecret: string;
}): Promise<unknown> {
    const { bountyId, posterSecret } = params;
    const res = await api.post(
        `/bounties/${encodeURIComponent(bountyId)}/reject-candidates`,
        {
            poster_secret: posterSecret,
        }
    );
    return extractData<unknown>(res.data);
}

export async function syncBountyJobStatus(params: {
    bountyId: string;
    posterSecret: string;
}): Promise<unknown> {
    const { bountyId, posterSecret } = params;
    const res = await api.post(
        `/bounties/${encodeURIComponent(bountyId)}/job-status`,
        {
            poster_secret: posterSecret,
        }
    );
    return extractData<unknown>(res.data);
}

// =============================================================================
// Axios HTTP client for the ACP API.
// =============================================================================

import axios from "axios";
import dotenv from "dotenv";
import { loadApiKey } from "./config.js";

dotenv.config();

// Ensure API key is loaded from config
loadApiKey();

const client = axios.create({
  baseURL: process.env.ACP_API_URL || "https://claw-api.virtuals.io",
  headers: {
    "x-api-key": process.env.LITE_AGENT_API_KEY,
  },
});

client.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response) {
      throw new Error(JSON.stringify(error.response.data));
    }
    throw error;
  }
);

export default client;

// =============================================================================
// Configuration file management.
// Reads/writes config.json at the repo root.
// =============================================================================

import * as fs from "fs";
import * as path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/** Repo root — two levels up from src/lib/ */
export const ROOT = path.resolve(__dirname, "..", "..");
export const CONFIG_JSON_PATH = path.resolve(ROOT, "config.json");
export const LOGS_DIR = path.resolve(ROOT, "logs");

export interface AgentEntry {
  id: string;
  name: string;
  walletAddress: string;
  apiKey: string | undefined; // only present for active/previously-switched agents
  active: boolean;
}

export interface RailwayProjectConfig {
  project: string;
  environment: string;
}

export interface DeployInfo {
  provider: string;
  agentName: string;
  offerings: string[];
  deployedAt: string;
  railwayConfig: RailwayProjectConfig;
}

export interface ConfigJson {
  SESSION_TOKEN?: {
    token: string;
  };
  LITE_AGENT_API_KEY?: string;
  SELLER_PID?: number;
  OPENCLAW_BOUNTY_CRON_JOB_ID?: string;
  agents?: AgentEntry[];
  DEPLOYS?: Record<string, DeployInfo>; // keyed by agent ID
}

export function readConfig(): ConfigJson {
  if (!fs.existsSync(CONFIG_JSON_PATH)) {
    return {};
  }
  try {
    const content = fs.readFileSync(CONFIG_JSON_PATH, "utf-8");
    return JSON.parse(content);
  } catch {
    return {};
  }
}

export function writeConfig(config: ConfigJson): void {
  try {
    fs.writeFileSync(CONFIG_JSON_PATH, JSON.stringify(config, null, 2) + "\n");
  } catch (err) {
    console.error(`Failed to write config.json: ${err}`);
  }
}

/** Load the API key from config.json or environment. */
export function loadApiKey(): string | undefined {
  if (process.env.LITE_AGENT_API_KEY?.trim()) {
    return process.env.LITE_AGENT_API_KEY.trim();
  }
  const config = readConfig();
  const key = config.LITE_AGENT_API_KEY;
  if (typeof key === "string" && key.trim()) {
    process.env.LITE_AGENT_API_KEY = key;
    return key;
  }
  return undefined;
}

/** Ensure API key is loaded, or exit with error. */
export function requireApiKey(): string {
  const key = loadApiKey();
  if (!key) {
    console.error(
      "Error: LITE_AGENT_API_KEY is not set. Run `acp setup` first."
    );
    process.exit(1);
  }
  return key;
}

export function isProcessRunning(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (err: any) {
    return err.code !== "ESRCH";
  }
}

export function writePidToConfig(pid: number): void {
  try {
    const config = readConfig();
    config.SELLER_PID = pid;
    writeConfig(config);
  } catch (err) {
    console.error(`Failed to write PID to config.json: ${err}`);
  }
}

export function removePidFromConfig(): void {
  try {
    const config = readConfig();
    if (config.SELLER_PID !== undefined) {
      delete config.SELLER_PID;
      writeConfig(config);
    }
  } catch {
    // Best effort cleanup
  }
}

export function checkForExistingProcess(): void {
  const config = readConfig();

  if (config.SELLER_PID !== undefined) {
    if (isProcessRunning(config.SELLER_PID)) {
      console.error(
        `Seller process already running with PID: ${config.SELLER_PID}`
      );
      console.error(
        "Please stop the existing process before starting a new one."
      );
      process.exit(1);
    } else {
      removePidFromConfig();
    }
  }
}

/** Find the PID of a running seller process (config check + OS fallback). */
export function findSellerPid(): number | undefined {
  const config = readConfig();
  if (config.SELLER_PID !== undefined && isProcessRunning(config.SELLER_PID)) {
    return config.SELLER_PID;
  }
  if (config.SELLER_PID !== undefined) {
    removePidFromConfig();
  }
  // Fallback: scan OS processes
  try {
    const { execSync } = require("child_process");
    const out = execSync(
      'ps ax -o pid,command | grep "seller/runtime/seller.ts" | grep -v grep',
      { encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] }
    );
    for (const line of out.trim().split("\n")) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      const pid = parseInt(trimmed.split(/\s+/)[0], 10);
      if (!isNaN(pid) && pid !== process.pid) return pid;
    }
  } catch {
    // grep returns exit code 1 when no matches
  }
  return undefined;
}

/** Get the currently active agent from the agents array. */
export function getActiveAgent(): AgentEntry | undefined {
  const config = readConfig();
  return config.agents?.find((a) => a.active);
}

/** Find an agent by name (case-insensitive). */
export function findAgentByName(name: string): AgentEntry | undefined {
  const config = readConfig();
  return config.agents?.find(
    (a) => a.name.toLowerCase() === name.toLowerCase()
  );
}

/** Activate an agent with a (possibly new) API key. Updates active flags and LITE_AGENT_API_KEY. */
export function activateAgent(agentId: string, apiKey: string): void {
  const config = readConfig();
  const agents = (config.agents ?? []).map((a) => ({
    ...a,
    active: a.id === agentId,
    apiKey: a.id === agentId ? apiKey : a.apiKey,
  }));

  writeConfig({
    ...config,
    agents,
    LITE_AGENT_API_KEY: apiKey,
  });
}

/** Sanitize an agent name for use as a directory name. */
export function sanitizeAgentName(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

export function formatPrice(price: unknown, priceType?: unknown): string {
  const p = price != null ? String(price) : "-";
  const type = String(priceType).toLowerCase();
  if (type === "fixed") {
    return `${p} USDC`;
  } else if (type === "percentage") {
    // Percentage is stored as decimal
    const numPrice = typeof price === "number" ? price : parseFloat(p);
    if (!isNaN(numPrice)) {
      return `${(numPrice * 100).toFixed(2)}%`;
    }
    return `${p}%`;
  } else if (priceType != null) {
    return `${p} ${priceType}`;
  }
  return p;
}

// =============================================================================
// Open a URL in the user's default browser. Platform-specific, no dependencies.
// =============================================================================

import { exec } from "child_process";

export function openUrl(url: string): void {
  const platform = process.platform;
  let cmd: string;

  if (platform === "darwin") {
    cmd = `open "${url}"`;
  } else if (platform === "win32") {
    cmd = `start "" "${url}"`;
  } else {
    // Linux / others
    cmd = `xdg-open "${url}"`;
  }

  exec(cmd, (err) => {
    if (err) {
      // Silently fail — the URL is always printed as fallback
    }
  });
}

// =============================================================================
// OpenClaw cron integration for bounty polling.
//
// Uses the OpenClaw Gateway CLI (`openclaw cron add/remove`) to manage a
// recurring cron job that polls bounty status.
//
// The Gateway cron system runs *agent turns* (not arbitrary shell commands).
// We create an isolated agentTurn job whose prompt instructs the agent to
// run `acp bounty poll --json` and act on the results.
// =============================================================================

import { execSync } from "child_process";
import { ROOT, readConfig, writeConfig } from "./config.js";
import { listActiveBounties } from "./bounty.js";

const DEFAULT_JOB_ID = "openclaw-acp-bounty-poll";
const DEFAULT_SCHEDULE = "*/10 * * * *";

const POLL_SYSTEM_EVENT = [
    `[ACP Bounty Poll] This is an automated bounty check. You MUST:`,
    `1. Run this command: cd "${ROOT}" && npx acp bounty poll --json`,
    `2. Parse the JSON output and check the pendingMatch, claimedJobs, cleaned, and errors arrays.`,
    ``,
    `3. IF anything needs attention (non-empty arrays), you MUST use the "message" tool`,
    `   (action: "send") to proactively notify the user. Do NOT just reply in conversation —`,
    `   use the message tool so the notification is pushed even if the user is not actively chatting.`,
    ``,
    `   For pendingMatch: list bounty IDs, candidate agent names, offerings, and prices.`,
    `   Filter out irrelevant or malicious candidates. Ask which candidate to select.`,
    `   For claimedJobs: report job phase/status.`,
    `   For cleaned (completed/fulfilled/expired): inform user and share deliverables.`,
    `   For errors: report them.`,
    ``,
    `4. IF everything is empty (all arrays are empty or zero), reply HEARTBEAT_OK.`,
    `   Do NOT message the user when there is nothing to report.`,
].join("\n");

function runCli(args: string[]): string {
    return execSync(`openclaw cron ${args.join(" ")}`, {
        cwd: ROOT,
        stdio: ["ignore", "pipe", "pipe"],
        encoding: "utf-8",
    }).trim();
}

export function getBountyPollCronJobId(): string {
    const cfg = readConfig();
    return (
        cfg.OPENCLAW_BOUNTY_CRON_JOB_ID ||
        process.env.OPENCLAW_BOUNTY_CRON_JOB_ID ||
        DEFAULT_JOB_ID
    );
}

export function ensureBountyPollCron(): { enabled: boolean; created: boolean } {
    if (process.env.OPENCLAW_BOUNTY_CRON_DISABLED === "1") {
        return { enabled: false, created: false };
    }

    const cfg = readConfig();
    if (cfg.OPENCLAW_BOUNTY_CRON_JOB_ID) {
        // Cron job already registered — nothing to do.
        return { enabled: true, created: false };
    }

    const schedule =
        process.env.OPENCLAW_BOUNTY_CRON_SCHEDULE?.trim() || DEFAULT_SCHEDULE;

    // Create a main-session systemEvent cron job via the OpenClaw CLI.
    // This injects the poll instruction into the main session so the agent
    // can present candidates interactively and ask the user to pick.
    const result = runCli([
        "add",
        "--name", JSON.stringify("ACP Bounty Poll"),
        "--cron", JSON.stringify(schedule),
        "--session", "main",
        "--system-event", JSON.stringify(POLL_SYSTEM_EVENT),
        "--wake", "now",
    ]);

    // Parse the job id from CLI output (JSON object with "id" field).
    let jobId: string | undefined;
    try {
        const parsed = JSON.parse(result);
        jobId = parsed.id || parsed.jobId;
    } catch {
        // If output isn't JSON, try to extract a UUID-like id.
        const match = result.match(
            /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i
        );
        if (match) jobId = match[0];
    }

    if (!jobId) {
        throw new Error(
            `Failed to parse cron job id from OpenClaw CLI output: ${result}`
        );
    }

    writeConfig({ ...cfg, OPENCLAW_BOUNTY_CRON_JOB_ID: jobId });
    return { enabled: true, created: true };
}

export function removeBountyPollCronIfUnused(): {
    enabled: boolean;
    removed: boolean;
} {
    if (process.env.OPENCLAW_BOUNTY_CRON_DISABLED === "1") {
        return { enabled: false, removed: false };
    }

    const active = listActiveBounties();
    if (active.length > 0) {
        return { enabled: true, removed: false };
    }

    const cfg = readConfig();
    const jobId = cfg.OPENCLAW_BOUNTY_CRON_JOB_ID;
    if (!jobId) {
        return { enabled: true, removed: false };
    }

    try {
        runCli(["remove", jobId]);
    } catch {
        // Job may already be gone — that's fine.
    }

    const next = readConfig();
    delete next.OPENCLAW_BOUNTY_CRON_JOB_ID;
    writeConfig(next);
    return { enabled: true, removed: true };
}

// =============================================================================
// Dual-mode output: human-friendly (default) vs JSON (--json flag / ACP_JSON=1)
// With ANSI color support for TTY terminals.
// =============================================================================

let jsonMode = false;

export function setJsonMode(enabled: boolean): void {
  jsonMode = enabled;
}

export function isJsonMode(): boolean {
  return jsonMode;
}

// -- ANSI colors (only when stdout is a TTY and not in JSON mode) --

const isTTY = process.stdout.isTTY === true;

const c = {
  bold: (s: string) => (isTTY && !jsonMode ? `\x1b[1m${s}\x1b[0m` : s),
  dim: (s: string) => (isTTY && !jsonMode ? `\x1b[2m${s}\x1b[0m` : s),
  green: (s: string) => (isTTY && !jsonMode ? `\x1b[32m${s}\x1b[0m` : s),
  red: (s: string) => (isTTY && !jsonMode ? `\x1b[31m${s}\x1b[0m` : s),
  yellow: (s: string) => (isTTY && !jsonMode ? `\x1b[33m${s}\x1b[0m` : s),
  cyan: (s: string) => (isTTY && !jsonMode ? `\x1b[36m${s}\x1b[0m` : s),
};

export { c as colors };

// -- Output functions --

/** Print JSON to stdout (for --json mode or agent consumption). */
export function json(data: unknown): void {
  console.log(JSON.stringify(data, null, jsonMode ? undefined : 2));
}

/** Print a line to stdout (human mode). Suppressed in JSON mode. */
export function log(msg: string): void {
  if (!jsonMode) console.log(msg);
}

/** Print an error line to stderr. Always shown. */
export function error(msg: string): void {
  if (jsonMode) {
    console.error(JSON.stringify({ error: msg }));
  } else {
    console.error(c.red(`Error: ${msg}`));
  }
}

/** Print a success line (human mode). Suppressed in JSON mode. */
export function success(msg: string): void {
  if (!jsonMode) console.log(c.green(`  ${msg}`));
}

/** Print a warning line (human mode). Suppressed in JSON mode. */
export function warn(msg: string): void {
  if (!jsonMode) console.log(c.yellow(`  Warning: ${msg}`));
}

/** Print a section heading. */
export function heading(title: string): void {
  if (!jsonMode) {
    console.log(`\n${c.bold(title)}`);
    console.log(c.dim("-".repeat(50)));
  }
}

/** Print a key-value pair. */
export function field(
  label: string,
  value: string | number | boolean | null | undefined
): void {
  if (!jsonMode) {
    console.log(`  ${c.dim(label.padEnd(18))} ${value ?? "-"}`);
  }
}

/**
 * Output data in the appropriate mode.
 * In JSON mode: prints JSON to stdout.
 * In human mode: calls the formatter function.
 */
export function output(
  data: unknown,
  humanFormatter: (data: any) => void
): void {
  if (jsonMode) {
    json(data);
  } else {
    humanFormatter(data);
  }
}

/** Fatal error — print and exit. */
export function fatal(msg: string): never {
  error(msg);
  process.exit(1);
}

export function formatSymbol(symbol: string): string {
  return symbol[0].startsWith("$") ? symbol : `$${symbol}`;
}

